import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"API 版本管理","description":"版本不是越多越好，而是用最小成本让破坏性变更不伤到已有客户端。","frontmatter":{"title":"API 版本管理","description":"版本不是越多越好，而是用最小成本让破坏性变更不伤到已有客户端。"},"headers":[],"relativePath":"backend/api-versioning.md","filePath":"backend/api-versioning.md","lastUpdated":1786271684000}'),d={name:"backend/api-versioning.md"};function i(p,t,o,l,r,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="api-版本管理" tabindex="-1">API 版本管理 <a class="header-anchor" href="#api-版本管理" aria-label="Permalink to &quot;API 版本管理&quot;">​</a></h1><p>API 一旦上线就有了外部调用方，再想改字段含义或返回结构，就不再是&quot;改个代码&quot;那么简单。版本管理的本质是：<strong>用一套明确的规则，让你能安全演进接口，同时不强迫所有客户端同时升级</strong>。它的目标不是把每个小改动都包成一个新版本，而是只在真正破坏兼容性时才动用版本这个重武器。</p><h2 id="为什么需要版本" tabindex="-1">为什么需要版本 <a class="header-anchor" href="#为什么需要版本" aria-label="Permalink to &quot;为什么需要版本&quot;">​</a></h2><p>判断一个改动是否需要版本，关键看它是不是<strong>破坏性变更</strong>（breaking change）：</p><table tabindex="0"><thead><tr><th>改动类型</th><th>是否破坏性</th><th>是否需要版本</th></tr></thead><tbody><tr><td>新增可选字段</td><td>否</td><td>否</td></tr><tr><td>新增接口</td><td>否</td><td>否</td></tr><tr><td>删除字段</td><td>是</td><td>是</td></tr><tr><td>改字段含义</td><td>是</td><td>是</td></tr><tr><td>改字段类型（string → int）</td><td>是</td><td>是</td></tr><tr><td>收紧校验规则</td><td>是</td><td>是</td></tr><tr><td>枚举值变动</td><td>看情况</td><td>通常需要</td></tr></tbody></table><p>最容易踩的坑是&quot;收紧校验&quot;和&quot;改字段含义&quot;——它们不报错、不缺字段，但客户端按旧约定处理就会出错。这类隐性破坏比显式删字段更危险。</p><blockquote><p>一条铁律：<strong>新增是免费的，删除和改义是昂贵的</strong>。能加字段就别改字段。</p></blockquote><h2 id="版本策略对比" tabindex="-1">版本策略对比 <a class="header-anchor" href="#版本策略对比" aria-label="Permalink to &quot;版本策略对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>形式</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>URL 版本</td><td><code>/v1/users</code>、<code>/v2/users</code></td><td>显式、好调试、缓存友好</td><td>路径膨胀，多版本并存成本高</td></tr><tr><td>Header 版本</td><td><code>Accept: application/vnd.x.v2+json</code></td><td>URL 干净，可内容协商</td><td>不直观、难调试、CDN 易出错</td></tr><tr><td>查询参数</td><td><code>?version=2</code></td><td>改动小</td><td>易被忽略、缓存语义混乱</td></tr><tr><td>语义版本</td><td>整体 <code>v2.3.1</code></td><td>表达力强</td><td>对 HTTP API 偏重，多用于 SDK/包</td></tr></tbody></table><p>对大多数 HTTP API，<strong>URL 版本是最务实的选择</strong>：一眼能看出在调哪个版本，文档、Mock、监控都好对齐。Header 版本看似优雅，但调试时谁也记不住要带哪个 Accept，反而成了负担。</p><h2 id="向后兼容的边界" tabindex="-1">向后兼容的边界 <a class="header-anchor" href="#向后兼容的边界" aria-label="Permalink to &quot;向后兼容的边界&quot;">​</a></h2><p>不是所有变更都值得开新版本。可以安全地、不开版本地做的&quot;兼容性扩展&quot;：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ 新增返回字段（客户端忽略未知字段即可）</span></span>
<span class="line"><span>✓ 新增可选请求参数</span></span>
<span class="line"><span>✓ 新增接口端点</span></span>
<span class="line"><span>✓ 放宽校验（原本拒绝的现在接受）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✗ 删除或重命名字段</span></span>
<span class="line"><span>✗ 改变字段类型</span></span>
<span class="line"><span>✗ 改变错误码语义</span></span>
<span class="line"><span>✗ 收紧校验（原本接受的现在拒绝）</span></span></code></pre></div><blockquote><p>客户端能否&quot;忽略未知字段&quot;，是兼容性的前提。如果客户端用强类型反序列化且严格校验，连新增字段都可能破坏它。上线前确认你的客户端约定。</p></blockquote><p>兼容性的边界要提前和团队约定清楚：<strong>默认宽松读取、严格写入</strong>。读端宽容未知字段，写端允许额外字段被忽略。这样后续扩展才不会被迫开新版本。</p><h2 id="废弃流程-不要直接删" tabindex="-1">废弃流程：不要直接删 <a class="header-anchor" href="#废弃流程-不要直接删" aria-label="Permalink to &quot;废弃流程：不要直接删&quot;">​</a></h2><p>破坏性变更的正确路径是&quot;先标记废弃，再在新版本移除&quot;，而不是一刀切：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 在 v1 中字段继续返回，但加 deprecation 标记</span></span>
<span class="line"><span>2. 文档和响应头提示客户端迁移（Sunset / Deprecation header）</span></span>
<span class="line"><span>3. 观察旧字段的实际使用，给足迁移时间</span></span>
<span class="line"><span>4. 在 v2 中正式移除，v1 保持可用直到迁移完成</span></span></code></pre></div><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Deprecation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Sunset</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Wed, 31 Dec 2025 23:59:59 GMT</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Link</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;/v2/users&gt;; rel=&quot;successor-version&quot;</span></span></code></pre></div><p>废弃周期长短取决于你有多少外部调用方、它们升级多快。内部 API 几周够了，开放平台可能要按年计。<strong>直接删字段等于对客户端发动一次线上故障</strong>，这是 API 设计里最该避免的操作。</p><h2 id="同时维护多版本的成本" tabindex="-1">同时维护多版本的成本 <a class="header-anchor" href="#同时维护多版本的成本" aria-label="Permalink to &quot;同时维护多版本的成本&quot;">​</a></h2><p>每多一个并存版本，维护成本就上一个台阶：</p><table tabindex="0"><thead><tr><th>成本项</th><th>影响</th></tr></thead><tbody><tr><td>代码路径</td><td>每个 bugfix 要在多版本重复</td></tr><tr><td>文档</td><td>需要维护多套说明</td></tr><tr><td>测试</td><td>多版本回归矩阵膨胀</td></tr><tr><td>数据模型</td><td>不同版本的字段映射带来转换层</td></tr><tr><td>运维认知</td><td>排查问题要先确认在哪个版本</td></tr></tbody></table><blockquote><p>经验值：<strong>同时维护超过 2 个版本，通常意味着前面的废弃流程没做好</strong>。</p></blockquote><p>务实的做法是：默认只维护一个稳定版本 + 一个即将上线的版本；老版本给出明确的下线时间表。允许&quot;多版本共存&quot;不等于&quot;多版本永久共存&quot;。</p><h2 id="schema-演进-可选字段与枚举扩展" tabindex="-1">Schema 演进：可选字段与枚举扩展 <a class="header-anchor" href="#schema-演进-可选字段与枚举扩展" aria-label="Permalink to &quot;Schema 演进：可选字段与枚举扩展&quot;">​</a></h2><p>在不破坏兼容的前提下演进数据结构，有几条安全规则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ 字段只增不删（要删先废弃再在新版本移除）</span></span>
<span class="line"><span>✓ 新字段设为可选，给默认值</span></span>
<span class="line"><span>✓ 枚举只追加新值，不删旧值</span></span>
<span class="line"><span>✓ 用包装类型表达&quot;可能没有&quot;，避免 null 歧义</span></span></code></pre></div><p>枚举扩展是最容易翻车的：服务端加了一个 <code>status: &quot;archived&quot;</code>，老客户端的 <code>switch</code> 没有 <code>default</code> 分支，直接崩了或把未知值当错误处理。<strong>约定&quot;未知枚举值必须被容忍&quot;</strong>，是跨版本演进能成立的前提。</p><h2 id="与客户端协商" tabindex="-1">与客户端协商 <a class="header-anchor" href="#与客户端协商" aria-label="Permalink to &quot;与客户端协商&quot;">​</a></h2><p>版本不是服务端单方面的事。要让客户端在请求里带上自己能理解的版本，并在响应里告诉客户端&quot;这些字段即将废弃&quot;。常用的协商手段：</p><table tabindex="0"><thead><tr><th>方式</th><th>谁主导</th><th>适合</th></tr></thead><tbody><tr><td>客户端指定 URL 版本</td><td>客户端</td><td>明确、可控</td></tr><tr><td>服务端按客户端能力返回</td><td>服务端</td><td>客户端无感知升级</td></tr><tr><td>响应头提示废弃</td><td>双方</td><td>配合迁移周期</td></tr></tbody></table><p>无论用哪种，核心是<strong>让&quot;谁在用哪个版本&quot;可观测</strong>。没有这层可见性，废弃和下线就只能靠猜。</p><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>区分破坏性变更和兼容性扩展，只在破坏时才动用版本。</li><li>优先 URL 版本，调试和工具链支持都更好。</li><li>默认客户端&quot;忽略未知字段&quot;，这是向后兼容的地基。</li><li>废弃要走&quot;标记 → 观察 → 迁移 → 移除&quot;流程，绝不直接删。</li><li>限制同时维护的版本数，超过 2 个通常是废弃流程出了问题。</li><li>枚举只追加不删除，并约定未知值必须被容忍。</li><li>让&quot;谁在用哪个版本&quot;可观测，否则下线只能靠猜。</li></ul>`,35)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
